function.script:
function addListItem(listId, text) {
  const list = document.getElementById(listId);
  if (!list) return;
  const li = document.createElement('li');
  li.textContent = text;
  list.appendChild(li);
}
function removeListItem(listId, index) {
  const list = document.getElementById(listId);
  if (!list || !list.children[index]) return;
  list.removeChild(list.children[index]);
}
function clearList(listId) {
  const list = document.getElementById(listId);
  if (list) list.innerHTML = '';
}

function submitForm(formId) {
  const form = document.getElementById(formId);
  if (!form) return;
  form.dispatchEvent(new Event('submit', { cancelable: true }));
}
function resetForm(formId) {
  const form = document.getElementById(formId);
  if (form) form.reset();
}
function getFormFieldValue(formId, fieldName) {
  const form = document.getElementById(formId);
  if (!form || !form.elements[fieldName]) return '';
  return form.elements[fieldName].value;
}
function setFormFieldValue(formId, fieldName, val) {
  const form = document.getElementById(formId);
  if (form && form.elements[fieldName]) {
    form.elements[fieldName].value = val;
  }
}

function toggleNavbarMenu(navId) {
  const nav = document.getElementById(navId);
  if (!nav) return;
  const menu = nav.querySelector('.nav-menu') || nav;
  menu.classList.toggle('active');
  if (menu.style.display === 'flex') {
    menu.style.display = 'none';
  } else {
    menu.style.display = 'flex';
  }
}
function setNavbarBrand(navId, brandText) {
  const nav = document.getElementById(navId);
  if (!nav) return;
  const brand = nav.querySelector('.nav-brand');
  if (brand) brand.textContent = brandText;
}

function filterTable(tableId, query) {
  const table = document.getElementById(tableId);
  if (!table) return;
  const rows = table.querySelectorAll('tbody tr');
  rows.forEach(row => {
    row.style.display = row.innerText.toLowerCase().includes(query.toLowerCase()) ? '' : 'none';
  });
}
function sortTable(tableId, colIndex) {
  const table = document.getElementById(tableId);
  if (!table) return;
  const tbody = table.querySelector('tbody') || table;
  const rows = Array.from(tbody.querySelectorAll('tr'));
  rows.sort((a, b) => a.cells[colIndex].innerText.localeCompare(b.cells[colIndex].innerText));
  rows.forEach(r => tbody.appendChild(r));
}

function setProgress(barId, percent) {
  const el = barId && (barId.startsWith('#') || barId.startsWith('.')) ? document.querySelector(barId) : (document.getElementById(barId) || document.querySelector(barId));
  if (!el) return;
  const fill = el.querySelector('.progress-fill') || el;
  fill.style.width = Math.min(100, Math.max(0, percent)) + '%';
}
function incrementProgress(barId, amount) {
  const el = barId && (barId.startsWith('#') || barId.startsWith('.')) ? document.querySelector(barId) : (document.getElementById(barId) || document.querySelector(barId));
  if (!el) return;
  const fill = el.querySelector('.progress-fill') || el;
  const current = parseFloat(fill.style.width) || 0;
  setProgress(barId, current + amount);
}

function toggleAccordion(accId) {
  const acc = document.getElementById(accId);
  if (!acc) return;
  const body = acc.querySelector('.accordion-body');
  const icon = acc.querySelector('.accordion-icon');
  if (body) {
    const isOpen = body.style.display !== 'none';
    body.style.display = isOpen ? 'none' : 'block';
    if (icon) icon.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
  }
}

function openModal(modalId) {
  const m = document.getElementById(modalId);
  if (m) m.style.display = 'block';
}
function closeModal(modalId) {
  const m = document.getElementById(modalId);
  if (m) m.style.display = 'none';
}

function carouselNext(cId) {
  const c = document.getElementById(cId);
  if (!c) return;
  const slides = c.querySelectorAll('.carousel-slide');
  let cur = Array.from(slides).findIndex(s => s.classList.contains('active'));
  if (cur >= 0) {
    slides[cur].classList.remove('active');
    slides[(cur + 1) % slides.length].classList.add('active');
  }
}
function carouselPrev(cId) {
  const c = document.getElementById(cId);
  if (!c) return;
  const slides = c.querySelectorAll('.carousel-slide');
  let cur = Array.from(slides).findIndex(s => s.classList.contains('active'));
  if (cur >= 0) {
    slides[cur].classList.remove('active');
    slides[(cur - 1 + slides.length) % slides.length].classList.add('active');
  }
}

function showToast(toastId, msg) {
  const t = document.getElementById(toastId);
  if (!t) return;
  if (msg) {
    const textEl = t.querySelector('.toast-text') || t;
    textEl.textContent = msg;
  }
  t.style.display = 'flex';
  setTimeout(() => { t.style.display = 'none'; }, 3500);
}
function hideToast(toastId) {
  const t = document.getElementById(toastId);
  if (t) t.style.display = 'none';
}

function toggleDropdown(ddId) {
  const dd = document.getElementById(ddId);
  if (!dd) return;
  const menu = dd.querySelector('.dropdown-menu');
  if (menu) menu.style.display = menu.style.display === 'block' ? 'none' : 'block';
}

function setRating(ratingId, stars) {
  const r = document.getElementById(ratingId);
  if (!r) return;
  r.setAttribute('data-rating', stars);
  const starEls = r.querySelectorAll('.star');
  starEls.forEach((s, idx) => {
    s.style.color = idx < stars ? '#F59E0B' : '#CBD5E1';
  });
}

function animateCounter(counterId, target) {
  const el = document.getElementById(counterId);
  if (!el) return;
  let cur = 0;
  const step = Math.ceil(target / 40);
  const timer = setInterval(() => {
    cur += step;
    if (cur >= target) { cur = target; clearInterval(timer); }
    el.textContent = cur.toLocaleString();
  }, 25);
}
